+		return _cars;
+	}
+	
+	public int[] getFreeCarIds() {
+		return _freeCarIds;
+	}
+	
+	public Player getPlayer() {
+		return _player;
+	}
+	
+	public Position getNextCheckpoint() {
+		return _nextCheckpoint;
+	}
