341	+	
342	+	private static final float CONTROL_SENSITY = 2.f;
343	+	protected static final long MAX_CONTROL_WAIT = 10;
344	+	
345	+	private volatile boolean _running;
346	+	protected boolean _speedUp;
347	+	protected boolean _speedDown;
348	+	protected boolean _steerLeft;
349	+	protected boolean _steerRight;
350	+	
