361	+		_direction = 0.f;
362	+		
363	+		_playerClient = PlayerSimulatorWindow.getInstance().getPlayerClient();
364	+		
365	+		_keyHandler = new UnprocessedKeyHandler.Adapter() {
366	+			@Override
367	+			public void keyPressed(int keyCode, KeyLocation keyLocation) {
368	+				switch (keyCode) {
369	+					case KeyCode.W:
370	+						_speedUp = true;
371	+						break;
372	+					case KeyCode.S:
373	+						_speedDown = true;
374	+						break;
375	+					case KeyCode.A:
376	+						_steerLeft = true;
377	+						break;
378	+					case KeyCode.D:
379	+						_steerRight = true;
380	+						break;
381	+				}
382	+			}
383	+			
384	+			@Override
385	+			public void keyReleased(int keyCode, KeyLocation keyLocation) {
386	+				switch (keyCode) {
387	+					case KeyCode.W:
388	+						_speedUp = false;
389	+						break;
390	+					case KeyCode.S:
391	+						_speedDown = false;
392	+						break;
393	+					case KeyCode.A:
394	+						_steerLeft = false;
395	+						break;
396	+					case KeyCode.D:
397	+						_steerRight = false;
398	+						break;
399	+				}
400	+				
401	+			}
402	+		};
403	+	}
404	+	
405	+	public float getSpeed() {
406	+		return _speed;
407	+	}
