430	+	private void startControlThread() {
431	+		if (_running) {
432	+			return;
433	+		}
434	+		_running = true;
435	+		new Thread(this, "Car control thread").start();
436	+	}
437	+	
438	+	@Override
439	+	public void run() {
440	+		long lastUpdate = System.currentTimeMillis();
441	+		while (_running) {
442	+			long now = System.currentTimeMillis();
443	+			float sensity = (((now - lastUpdate) / 1000.f) * CONTROL_SENSITY);
444	+			if (_speedUp) {
445	+				_speed = Math.min(1.f, (_speed + sensity));
446	+			} else if (_speedDown) {
447	+				_speed = Math.max(-1.f, (_speed - sensity));
448	+			} else if (_speed < 0) {
449	+				_speed = Math.min(0.f, (_speed + sensity));
450	+			} else if (_speed > 0) {
451	+				_speed = Math.max(0.f, (_speed - sensity));
452	+			}
453	+			
454	+			if (_steerLeft) {
455	+				_direction = Math.max(-1.f, (_direction - sensity));
456	+			} else if (_steerRight) {
457	+				_direction = Math.min(1.f, (_direction + sensity));
458	+			} else if (_direction < 0) {
459	+				_direction = Math.min(0.f, (_direction + sensity));
460	+			} else if (_direction > 0) {
461	+				_direction = Math.max(0.f, (_direction - sensity));
462	+			}
463	+			
464	+			// TODO: _playerClient.getPlayerServer().updateVelocity(_speed, _direction);
465	+			
466	+			ApplicationContext.queueCallback(new Runnable() {
467	+				
468	+				@Override
469	+				public void run() {
470	+					repaint();
471	+				}
472	+			});
473	+			
474	+			long wait = MAX_CONTROL_WAIT - (System.currentTimeMillis() - lastUpdate);
475	+			lastUpdate = now;
476	+			if (wait > 0) {
477	+				try {
478	+					Thread.sleep(wait);
479	+				} catch (InterruptedException e) {
480	+					// TODO Auto-generated catch block
481	+					e.printStackTrace();
482	+				}
483	+			}
484	+		}
485	+	}
