507	+public class CarControlComponentSkin extends ComponentSkin {
508	+	
509	+	private static final int CONTROL_SIZE = 100;
510	+	private static final int CONTROL_PADDING = 10;
511	+	
512	+	private final CarControlComponent _component;
513	+	
514	+	private final BufferedImage _arrow;
515	+	
516	+	public CarControlComponentSkin(CarControlComponent carControlComponent) {
517	+		_component = carControlComponent;
518	+		try {
519	+			_arrow = ImageIO.read(CarControlComponentSkin.class.getResource("arrow.png"));
520	+		} catch (IOException e) {
521	+			throw new RuntimeException(e);
522	+		}
523	+	}
524	+	
525	+	@Override
526	+	public void layout() {
527	+		// no-op.
528	+	}
529	+	
530	+	@Override
531	+	public int getPreferredWidth(int height) {
532	+		return 0;
533	+	}
534	+	
535	+	@Override
536	+	public int getPreferredHeight(int width) {
537	+		return 0;
538	+	}
539	+	
540	+	@Override
541	+	public void paint(Graphics2D graphics) {
542	+		int width = getWidth();
543	+		int height = getHeight();
544	+		
545	+		int controlYCenter = height - (CONTROL_SIZE / 2);
546	+		int controlXCenter = (width / 2);
547	+		
548	+		int speedControlX = controlXCenter - (CONTROL_SIZE / 2);
549	+		int speedControlY = height - CONTROL_SIZE + CONTROL_PADDING;
550	+		graphics.setColor(Color.black);
551	+		graphics.drawLine(speedControlX, speedControlY, speedControlX, (height - CONTROL_PADDING));
552	+		graphics.drawLine((speedControlX - (CONTROL_PADDING * 2)), controlYCenter,
553	+				(speedControlX + (CONTROL_PADDING * 2)), controlYCenter);
554	+		
555	+		int speedControlValueY = controlYCenter
556	+				+ (int) (_component.getSpeed() * -1.f * ((CONTROL_SIZE / 2) - CONTROL_PADDING));
557	+		graphics.setColor(Color.red);
558	+		graphics.drawLine((speedControlX - CONTROL_PADDING), speedControlValueY,
559	+				(speedControlX + CONTROL_PADDING), speedControlValueY);
560	+		
561	+		int directionControlX = (controlXCenter + CONTROL_PADDING);
562	+		graphics.setColor(Color.black);
563	+		graphics.drawLine(directionControlX, controlYCenter,
564	+				(controlXCenter + CONTROL_SIZE - CONTROL_PADDING), controlYCenter);
565	+		int directionControlCenter = (controlXCenter + (CONTROL_SIZE / 2));
566	+		graphics.drawLine(directionControlCenter, (controlYCenter - (CONTROL_PADDING * 2)),
567	+				directionControlCenter, (controlYCenter + (CONTROL_PADDING * 2)));
568	+		
569	+		int directionControlValueX = directionControlCenter
570	+				+ (int) (_component.getDirection() * ((CONTROL_SIZE / 2) - CONTROL_PADDING));
571	+		graphics.setColor(Color.red);
572	+		graphics.drawLine(directionControlValueX, (controlYCenter - CONTROL_PADDING),
573	+				directionControlValueX, (controlYCenter + CONTROL_PADDING));
574	+		
575	+		Position next = _component.getNextCheckPoint();
576	+		if (next != null) {
577	+			int arrowCenterX = (width - CONTROL_SIZE) / 2;
578	+			int arrowCenterY = (height - CONTROL_SIZE) / 2;
579	+			
580	+			double distance = Math.sqrt(Math.pow(next.getPosX(), 2) + Math.pow(next.getPosY(), 2));
581	+			double scale = 1;
582	+			if (distance < 300.0) {
583	+				scale = (distance / 300.0);
584	+				scale = Math.max(0.01, scale);
585	+			}
586	+			
587	+			AffineTransform xform = new AffineTransform();
588	+			xform.translate(arrowCenterX, arrowCenterY);
589	+			xform.scale(scale, scale);
590	+			xform.translate(-_arrow.getWidth() / 2, -_arrow.getHeight() / 2);
591	+			xform.rotate(next.getPosX(), next.getPosY() * -1, _arrow.getWidth() / 2,
592	+					_arrow.getHeight() / 2);
593	+			graphics.drawImage(_arrow, xform, null);
594	+		}
595	+	}
596	+}
