1048	+	
1049	+	private Object _base;
1050	+	private Object _proxy;
1051	+	
1052	+	public PivotThreadProxy(Object base) throws IllegalArgumentException {
1053	+		if (base == null) {
1054	+			throw new IllegalArgumentException("base must not be null!");
1055	+		}
1056	+		
1057	+		_base = base;
1058	+		_proxy = createProxy(_base.getClass());
1059	+	}
1060	+	
1061	+	private Object createProxy(Class<?> baseClass) {
1062	+		Class<?> proxyClass = Proxy.getProxyClass(baseClass.getClassLoader(),
1063	+				baseClass.getInterfaces());
1064	+		Constructor<?> constructor;
1065	+		try {
1066	+			constructor = proxyClass.getConstructor(InvocationHandler.class);
1067	+			return constructor.newInstance(this);
1068	+		} catch (Exception e) {
1069	+			throw new RuntimeException("Couldn't create the requested proxy object.", e);
1070	+		}
1071	+	}
1072	+	
1073	+	public Object getProxy() {
1074	+		return _proxy;
1075	+	}
