1079	+		ApplicationContext.queueCallback(new Runnable() {
1080	+			
1081	+			@Override
1082	+			public void run() {
1083	+				try {
1084	+					method.invoke(_base, args);
1085	+				} catch (Exception e) {
1086	+					throw new RuntimeException(
1087	+							"Unexpected invocation exception: " + e.getMessage(), e);
1088	+				}
1089	+			}
1090	+		});
1091	+		
1092	+		return null;
1093	+	}
